script:
(function () {
  'use strict';
  // Spending cut invested: the cut is turned into a monthly amount (daily x 365 / 12, weekly x 52 /
  // 12, yearly / 12) and invested at the end of each month, growing at (annual return / 12).
  //   Optional yearly raise: the monthly amount grows by g each year (year y uses amount x (1+g)^(y-1)).
  //   Optional tax on earnings: monthly growth = (return / 12) x (1 - tax rate), as in a taxable
  //   account taxed every year.  Pay needed to fund the spending = amount / (1 - income tax rate).
  // Verified (Node scratch test vs independent Python): $100/month at 6% for 10 years = $16,387.93
  //   (standard annuity-table value); $5 a day = $152.08/month, at 6% for 20 years = $70,268.72 from
  //   $36,500 not spent. 0% return: balance = amount not spent; with a 25% income tax rate that
  //   spending needs $16,000 of pay for $12,000. 3% yearly raise + 20% tax on earnings: $17,407.99.
  //   Zero, negative or blank inputs show an error instead of NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function grow(monthly, i, years, g) {
    var bal = 0, put = 0, rows = [];
    for (var y = 1; y <= years; y++) {
      var pmt = monthly * Math.pow(1 + g, y - 1);
      for (var m = 0; m < 12; m++) {
        bal = bal * (1 + i) + pmt;
        put += pmt;
      }
      rows.push({ year: y, put: put, balance: bal });
    }
    return { balance: bal, put: put, rows: rows };
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function cell(tr, text) {
    var td = document.createElement('td');
    td.textContent = text;
    tr.appendChild(td);
  }

  function update() {
    var amount = num('bsAmount'), per = parseInt(document.getElementById('bsFreq').value, 10),
        years = Math.round(num('bsYears')), rate = num('bsRate'), raise = num('bsRaise'),
        tax = num('bsTax'), incomeTax = num('bsIncomeTax');
    var error = document.getElementById('bsError');
    var msg = '';
    if ([amount, years, rate, raise, tax, incomeTax].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (amount <= 0) msg = 'Enter the amount you would cut, above $0.';
    else if (years < 1 || years > 70) msg = 'Enter 1 to 70 years.';
    else if (rate < 0 || rate > 50) msg = 'Enter a rate of return from 0 to 50%.';
    else if (raise < 0 || raise > 20) msg = 'Enter a yearly increase from 0 to 20%.';
    else if (tax < 0 || tax >= 100 || incomeTax < 0 || incomeTax >= 100) msg = 'Enter tax rates from 0 to 99%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var monthly = amount * per / 12;
    var i = rate / 100 / 12 * (1 - tax / 100);
    var r = grow(monthly, i, years, raise / 100);

    set('bsBalanceLabel', 'Grows to in ' + years + (years === 1 ? ' year' : ' years'));
    set('bsBalance', money0.format(r.balance));
    set('bsMonthly', money.format(monthly));
    set('bsYearly', money0.format(monthly * 12));
    set('bsPut', money0.format(r.put));
    set('bsGrowth', money0.format(r.balance - r.put));
    set('bsPretax', money0.format(r.put / (1 - incomeTax / 100)));

    var body = document.getElementById('bsSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      cell(tr, String(row.year));
      cell(tr, money0.format(row.put));
      cell(tr, money0.format(row.balance - row.put));
      cell(tr, money0.format(row.balance));
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('bsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
